/// A PMMP block type tag (`BlockTypeTags`); [`State::has_type_tag`] tells a state's.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum TypeTag {
    /// `bamboo_mosaic`.
    BambooMosaic,
    /// `dirt`.
    Dirt,
    /// `fire`.
    Fire,
    /// `hanging_sign`.
    HangingSign,
    /// `huge_fungus_replaceable`.
    HugeFungusReplaceable,
    /// `mud`.
    Mud,
    /// `nylium`.
    Nylium,
    /// `pottable`.
    Pottable,
    /// `sand`.
    Sand,
}

/// The PMMP name of each type tag.
pub(super) static TYPE_TAG_NAMES: [&str; 9] = [
    "pocketmine:bamboo_mosaic",
    "pocketmine:dirt",
    "pocketmine:fire",
    "pocketmine:hanging_sign",
    "pocketmine:huge_fungus_replaceable",
    "pocketmine:mud",
    "pocketmine:nylium",
    "pocketmine:pottable",
    "pocketmine:sand",
];

